<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import { effectivePortraitOverrides } from '../composables/usePortraitSettings'
import { portraitDimensions } from '../composables/usePortraitFrames'
import { portraitFrame,portraitImageStyle,type ImageDimensions } from '../utils/portraitFraming'
import type { CharacterCrop } from '../types/characterEdit'
const props=defineProps<{uid:string;url:string}>()
const crop=defineModel<CharacterCrop|null>({default:null})
const dimensions=shallowRef<ImageDimensions|null>(null),error=shallowRef('')
watch(()=>props.url,async(url,previous,cleanup)=>{let alive=true;cleanup(()=>alive=false);dimensions.value=null;error.value='';const value=url?await portraitDimensions(url):null;if(!alive)return;dimensions.value=value;if(url&&!value)error.value='图片暂不可用，已保存取景保留。';else if(value&&!value.contentFingerprint)error.value='图片内容指纹暂不可读，暂不能保存新取景。';if(previous!==undefined&&url!==previous&&value?.contentFingerprint&&crop.value?.imageFingerprint!==value.contentFingerprint)crop.value={...current.value,imageFingerprint:value.contentFingerprint}}, {immediate:true})
const valid=computed(()=>!!dimensions.value?.contentFingerprint)
const automatic=computed(()=>portraitFrame(props.uid,props.url,dimensions.value,'auto',1,effectivePortraitOverrides.value))
const current=computed<CharacterCrop>(()=>{if(crop.value&&crop.value.imageFingerprint===dimensions.value?.contentFingerprint)return crop.value;const f=automatic.value,clamp=(n:number,min=0,max=1)=>Math.max(min,Math.min(max,n));return {mode:f.full?'full':'portrait',focalX:clamp(f.x/100),focalY:clamp(f.y/100),scale:clamp(f.width/Math.max(100,100*(dimensions.value?dimensions.value.width/dimensions.value.height:1)),1,3),imageFingerprint:dimensions.value?.contentFingerprint||''}})
function update(key:keyof CharacterCrop,value:string|number){if(!valid.value)return;crop.value={...current.value,[key]:value}}
const preview=computed(()=>portraitImageStyle(crop.value&&crop.value.imageFingerprint===dimensions.value?.contentFingerprint?portraitFrame(props.uid,props.url,dimensions.value,'auto',1,[{...current.value,entityUid:props.uid,reviewed:true}]):automatic.value))
let drag:{x:number;y:number;focalX:number;focalY:number;id:number}|undefined
function down(event:PointerEvent){if(!valid.value)return;drag={x:event.clientX,y:event.clientY,focalX:current.value.focalX,focalY:current.value.focalY,id:event.pointerId};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
function move(event:PointerEvent){if(!drag||drag.id!==event.pointerId)return;const clamp=(n:number)=>Math.max(0,Math.min(1,n));crop.value={...current.value,mode:'portrait',focalX:clamp(drag.focalX-(event.clientX-drag.x)/180),focalY:clamp(drag.focalY-(event.clientY-drag.y)/180)}}
</script>
<template><fieldset class="crop-editor"><legend>头像取景</legend><p>拖动预览调整位置，也可用滑块与键盘。{{ crop&&crop.imageFingerprint!==dimensions?.contentFingerprint?'图片内容已变化，旧取景暂不套用。':'' }}</p><p v-if="error" role="status">{{ error }}</p><div class="previews"><span v-for="shape in ['circle','card']" :key="shape" class="crop-preview" :class="shape" @pointerdown="down" @pointermove="move" @pointerup="drag=undefined" @pointercancel="drag=undefined"><img v-if="url&&dimensions" :src="url" :style="preview" alt="角色头像取景预览" draggable="false" referrerpolicy="no-referrer"><span v-else>图片待加载</span></span></div><div class="crop-controls"><label>显示模式<select :value="current.mode" :disabled="!valid" @change="update('mode',($event.target as HTMLSelectElement).value)"><option value="portrait">头像取景</option><option value="full">完整图片</option></select></label><label>横向位置<input :value="current.focalX" :disabled="!valid" type="range" min="0" max="1" step="0.01" @input="update('focalX',Number(($event.target as HTMLInputElement).value))"></label><label>纵向位置<input :value="current.focalY" :disabled="!valid" type="range" min="0" max="1" step="0.01" @input="update('focalY',Number(($event.target as HTMLInputElement).value))"></label><label>缩放 {{ current.scale.toFixed(1) }} 倍<input :value="current.scale" :disabled="!valid" type="range" min="1" max="3" step="0.05" @input="update('scale',Number(($event.target as HTMLInputElement).value))"></label></div><button type="button" @click="crop=null">恢复自动取景</button></fieldset></template>
<style scoped>.crop-editor{border:1px solid #d5e0d8;padding:16px;border-radius:8px;font-size:12px}.crop-editor p{line-height:1.8}.previews{display:flex;gap:30px;align-items:center;padding:10px}.crop-preview{position:relative;display:grid;place-items:center;width:120px;height:120px;overflow:hidden;background:#e9efe9;touch-action:none;cursor:grab;color:#476854}.circle{border-radius:50%}.card{border-radius:12px}.crop-preview img{position:absolute;max-width:none;pointer-events:none}.crop-controls{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.crop-controls label{font-size:12px;display:grid;gap:7px}@media(max-width:450px){.crop-controls{grid-template-columns:1fr}.crop-preview{width:100px;height:100px}.previews{gap:15px}}</style>
